// Production plan for the story mode, chapter by chapter. Every chapter is
// data: sub-missions, optional challenges, fixed canonical events, reflective
// decisions that always converge, the powers each character may use and the
// episode references to verify before building it. Synopses are paraphrased
// summaries written for this project; no script lines from the anime.
//
// status: 'playable' (implemented in story.html), 'prototype' (systems exist
// elsewhere in the repo) or 'planned'.

const m = (id, title, kind, objective) => ({ id, title, kind, objective });
const death = (who, staging) => ({ kind: 'death', who, staging });
const event = (id, staging) => ({ kind: 'event', id, staging });
// A decision never changes the canonical outcome: every option resolves into
// `resolves`. Options only change who the player saved locally, dialogue and
// the reflection shown in the chapter summary.
const decision = (id, prompt, options, resolves) => ({ id, prompt, options: options.map(([key, label, reflection]) => ({ id: key, label, reflection })), resolves });

